<?php
namespace App\Http\Controllers\Api\V1;
use App\Models\{Company,DeliveryOrder,SalesFulfillment,SalesFulfillmentLine,SalesOrder,SalesOrderItem,Warehouse};
use App\Services\{AuthorizationService,SalesNumberService};
use App\Support\{Decimal,TenantContext};
use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
final class SalesFulfillmentController {
 private function t():string{return app(TenantContext::class)->id();}
 private function auth(Request $r,string $p='sales.manage',?SalesFulfillment $f=null):void{abort_unless($r->user()&&app(AuthorizationService::class)->allows($r->user(),$this->t(),$p,$f?->company_id,$f?->branch_id),403);if($f)abort_unless($f->tenant_id===$this->t(),404);}
 private function q(Request $r){$q=SalesFulfillment::where('tenant_id',$this->t())->with(['order.customer','warehouse','lines.orderItem.variant.product']);if($r->filled('company_id'))$q->where('company_id',$r->string('company_id'));if($r->filled('branch_id'))$q->where('branch_id',$r->string('branch_id'));if($r->filled('warehouse_id'))$q->where('warehouse_id',$r->string('warehouse_id'));if($r->filled('state'))$q->where('state',$r->string('state'));if($r->filled('search'))$q->where(function($x)use($r){$s=$r->string('search');$x->where('number','ilike',"%{$s}%")->orWhereHas('order',fn($o)=>$o->where('number','ilike',"%{$s}%"));});return $q->latest();}
 public function index(Request $r){$this->auth($r);return response()->json(['data'=>$this->q($r)->paginate(min(max($r->integer('per_page',25),10),100))]);}
 public function summary(Request $r){$this->auth($r);$q=$this->q($r);$count=fn($s)=>(clone $q)->where('state',$s)->count();return response()->json(['data'=>['total'=>(clone $q)->count(),'pending_fulfillment'=>$count('draft'),'picking'=>$count('picking'),'packed'=>$count('packed'),'dispatched'=>$count('dispatched'),'delivered'=>$count('delivered'),'exceptions'=>(clone $q)->where('state','exception')->count()]]);}
 public function show(Request $r,SalesFulfillment $fulfillment){$this->auth($r,'sales.manage',$fulfillment);return response()->json(['data'=>$fulfillment->load(['order.customer','warehouse','lines.orderItem.variant.product','shipments.items','shipments.trackingEvents','shipments.pod','shipments.exceptions'])]);}
 public function store(Request $r){$this->auth($r);$d=$r->validate(['company_id'=>'required|uuid','branch_id'=>'nullable|uuid','sales_order_id'=>'required|uuid','warehouse_id'=>'required|uuid','requested_delivery_date'=>'nullable|date','priority'=>'nullable|in:low,normal,high,urgent','assigned_to'=>'nullable|uuid','shipping_address'=>'nullable|string','delivery_notes'=>'nullable|string','lines'=>'required|array|min:1','lines.*.sales_order_item_id'=>'required|uuid','lines.*.quantity'=>'required|numeric|gt:0']);$t=$this->t();$order=SalesOrder::where('tenant_id',$t)->where('company_id',$d['company_id'])->whereKey($d['sales_order_id'])->firstOrFail();abort_unless(in_array($order->state,['confirmed','partially_fulfilled'],true),422,'Only confirmed orders can be fulfilled.');abort_unless(Warehouse::where('tenant_id',$t)->where('company_id',$d['company_id'])->whereKey($d['warehouse_id'])->exists(),404);$f=DB::transaction(function()use($d,$order,$t,$r){$f=SalesFulfillment::create(['tenant_id'=>$t,'company_id'=>$d['company_id'],'branch_id'=>$d['branch_id']??$order->branch_id,'sales_order_id'=>$order->id,'warehouse_id'=>$d['warehouse_id'],'created_by'=>$r->user()->id,'assigned_to'=>$d['assigned_to']??null,'number'=>app(SalesNumberService::class)->next($t,'fulfillment'),'priority'=>$d['priority']??'normal','requested_delivery_date'=>$d['requested_delivery_date']??$order->requested_delivery_date,'shipping_address'=>$d['shipping_address']??$order->shipping_address,'delivery_notes'=>$d['delivery_notes']??null]);foreach($d['lines'] as $line){$item=SalesOrderItem::where('tenant_id',$t)->where('sales_order_id',$order->id)->whereKey($line['sales_order_item_id'])->lockForUpdate()->firstOrFail();$already=SalesFulfillmentLine::where('tenant_id',$t)->where('sales_order_item_id',$item->id)->sum('quantity');$remaining=Decimal::sub((string)$item->reserved_quantity,(string)$already);abort_if(Decimal::compare((string)$line['quantity'],$remaining)>0,422,'Fulfillment quantity exceeds reserved remaining quantity.');SalesFulfillmentLine::create(['tenant_id'=>$t,'fulfillment_id'=>$f->id,'sales_order_item_id'=>$item->id,'quantity'=>Decimal::normalize((string)$line['quantity'])]);}return $f;});return response()->json(['data'=>$f->load('lines')],201);}
 public function confirmPicking(Request $r,SalesFulfillment $fulfillment){$this->auth($r,'sales.manage',$fulfillment);$d=$r->validate(['lines'=>'required|array|min:1','lines.*.id'=>'required|uuid','lines.*.picked_quantity'=>'required|numeric|min:0']);DB::transaction(function()use($d,$fulfillment,$r){$f=SalesFulfillment::whereKey($fulfillment->id)->lockForUpdate()->firstOrFail();abort_unless(in_array($f->state,['draft','picking'],true),422);foreach($d['lines'] as $x){$l=$f->lines()->whereKey($x['id'])->lockForUpdate()->firstOrFail();$qty=Decimal::normalize((string)$x['picked_quantity']);abort_if(Decimal::compare($qty,(string)$l->quantity)>0,422,'Picked quantity exceeds fulfillment quantity.');$l->update(['picked_quantity'=>$qty,'state'=>Decimal::compare($qty,(string)$l->quantity)===0?'picked':'partial']);}$f->update(['state'=>'picking','picked_at'=>now()]);});return response()->json(['data'=>$fulfillment->fresh('lines')]);}
 public function completePacking(Request $r,SalesFulfillment $fulfillment){$this->auth($r,'sales.manage',$fulfillment);DB::transaction(function()use($fulfillment){$f=SalesFulfillment::whereKey($fulfillment->id)->lockForUpdate()->firstOrFail();abort_unless(in_array($f->state,['picking','packed'],true),422);$lines=$f->lines()->lockForUpdate()->get();abort_unless($lines->every(fn($l)=>Decimal::compare((string)$l->packed_quantity,(string)$l->picked_quantity)<=0),422);$lines->each(fn($l)=>$l->update(['packed_quantity'=>$l->picked_quantity]));$f->update(['state'=>'packed','packed_at'=>now()]);});return response()->json(['data'=>$fulfillment->fresh('lines')]);}
 public function createShipment(Request $r,SalesFulfillment $fulfillment){$this->auth($r,'sales.manage',$fulfillment);abort_unless(in_array($fulfillment->state,['packed','dispatched'],true),422);$d=$r->validate(['idempotency_key'=>'required|string|max:100','carrier'=>'nullable|string|max:100','carrier_service'=>'nullable|string|max:100','tracking_number'=>'nullable|string|max:150','tracking_url'=>'nullable|url|max:500','planned_dispatch_date'=>'nullable|date','expected_delivery_date'=>'nullable|date']);$t=$this->t();$existing=DeliveryOrder::where('tenant_id',$t)->where('idempotency_key',$d['idempotency_key'])->first();if($existing)return response()->json(['data'=>$existing]);$shipment=DB::transaction(function()use($d,$fulfillment,$t,$r){$s=DeliveryOrder::create(['tenant_id'=>$t,'company_id'=>$fulfillment->company_id,'branch_id'=>$fulfillment->branch_id,'warehouse_id'=>$fulfillment->warehouse_id,'fulfillment_id'=>$fulfillment->id,'sales_order_id'=>$fulfillment->sales_order_id,'created_by'=>$r->user()->id,'number'=>app(SalesNumberService::class)->next($t,'delivery'),'idempotency_key'=>$d['idempotency_key'],'shipment_status'=>'draft','state'=>'draft','carrier'=>$d['carrier']??null,'carrier_service'=>$d['carrier_service']??null,'tracking_number'=>$d['tracking_number']??null,'tracking_url'=>$d['tracking_url']??null,'planned_dispatch_date'=>$d['planned_dispatch_date']??null,'expected_delivery_date'=>$d['expected_delivery_date']??null]);foreach($fulfillment->lines as $l){$qty=Decimal::sub((string)$l->packed_quantity,(string)$l->dispatched_quantity);if(Decimal::compare($qty,'0')>0){$s->items()->create(['tenant_id'=>$t,'sales_order_item_id'=>$l->sales_order_item_id,'location_id'=>$fulfillment->order->items()->whereKey($l->sales_order_item_id)->value('preferred_location_id'),'quantity'=>$qty]);}}return $s;});return response()->json(['data'=>$shipment->load('items')],201);}
}
